-- Migration 007: IEBC special registration areas: prisons and diaspora.
-- Based on the IEBC/Kenya Gazette 21 June 2022 Fourth and Fifth Schedules.
-- Special areas are intentionally not forced into the ordinary county/constituency/ward hierarchy.
BEGIN;

CREATE TABLE IF NOT EXISTS special_registration_areas (
 special_area_id TEXT PRIMARY KEY,
 registration_area_code TEXT NOT NULL UNIQUE,
 registration_area_name TEXT NOT NULL,
 special_area_type TEXT NOT NULL CHECK (special_area_type IN ('PRISONS','DIASPORA')),
 election_reference_year INTEGER NOT NULL,
 source_url TEXT NOT NULL,
 source_publication_date DATE,
 created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS special_registration_centres (
 special_registration_centre_id TEXT PRIMARY KEY,
 special_area_id TEXT NOT NULL REFERENCES special_registration_areas(special_area_id) ON UPDATE CASCADE ON DELETE RESTRICT,
 registration_centre_code TEXT NOT NULL,
 registration_centre_name TEXT NOT NULL,
 country_name TEXT,
 source_url TEXT NOT NULL,
 created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE(special_area_id,registration_centre_code)
);

CREATE TABLE IF NOT EXISTS special_polling_stations (
 special_polling_station_id TEXT PRIMARY KEY,
 special_registration_centre_id TEXT NOT NULL REFERENCES special_registration_centres(special_registration_centre_id) ON UPDATE CASCADE ON DELETE RESTRICT,
 polling_station_code TEXT NOT NULL UNIQUE,
 polling_station_name TEXT NOT NULL,
 registered_voters INTEGER NOT NULL CHECK(registered_voters>=0),
 source_url TEXT NOT NULL,
 election_reference_year INTEGER NOT NULL,
 created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE(special_registration_centre_id,polling_station_code)
);

CREATE INDEX IF NOT EXISTS idx_special_centres_area ON special_registration_centres(special_area_id);
CREATE INDEX IF NOT EXISTS idx_special_stations_centre ON special_polling_stations(special_registration_centre_id);
CREATE INDEX IF NOT EXISTS idx_special_stations_year ON special_polling_stations(election_reference_year);

VALUES('SRC-IEBC-KG-2022-SPECIAL','Kenya Gazette 21 June 2022 — Prison and Diaspora voter schedules','OFFICIAL','Independent Electoral and Boundaries Commission','Fourth Schedule: registered voters per prison; Fifth Schedule: registered voters per country for Kenyans residing outside Kenya.','https://www.iebc.or.ke/uploads/resources/tpFfOlBLRh.pdf')
ON CONFLICT(source_id) DO NOTHING;

ON CONFLICT(special_area_id) DO NOTHING;

ON CONFLICT(special_registration_centre_id) DO NOTHING;

ON CONFLICT(special_polling_station_id) DO NOTHING;

COMMENT ON TABLE special_registration_areas IS 'IEBC-published prison and diaspora registration areas outside the ordinary county hierarchy.';
COMMENT ON TABLE special_registration_centres IS 'IEBC-published prison or diaspora registration centres; no ward is inferred.';
COMMENT ON TABLE special_polling_stations IS 'IEBC-published prison or diaspora polling stations and 2022 registered-voter counts.';

DO $$
DECLARE pv INTEGER; dv INTEGER; ps INTEGER; ds INTEGER;
BEGIN
 SELECT COALESCE(SUM(s.registered_voters),0),COUNT(*) INTO pv,ps
 FROM special_polling_stations s JOIN special_registration_centres c ON c.special_registration_centre_id=s.special_registration_centre_id
 JOIN special_registration_areas a ON a.special_area_id=c.special_area_id WHERE a.special_area_type='PRISONS' AND s.election_reference_year=2022;
 SELECT COALESCE(SUM(s.registered_voters),0),COUNT(*) INTO dv,ds
 FROM special_polling_stations s JOIN special_registration_centres c ON c.special_registration_centre_id=s.special_registration_centre_id
 JOIN special_registration_areas a ON a.special_area_id=c.special_area_id WHERE a.special_area_type='DIASPORA' AND s.election_reference_year=2022;
 IF pv<>7483 THEN RAISE EXCEPTION 'Prison voter total mismatch: %',pv; END IF;
 IF dv<>10443 THEN RAISE EXCEPTION 'Diaspora voter total mismatch: %',dv; END IF;
 IF ps<>106 THEN RAISE EXCEPTION 'Prison station row count mismatch: %',ps; END IF;
 IF ds<>27 THEN RAISE EXCEPTION 'Diaspora station row count mismatch: %',ds; END IF;
END $$;

COMMIT;
